    @Test
    void recallOnNonReleasedBatch_returns409() throws Exception {
        String batchKey = "BK-RC-EARLY-" + unique();
        createBatch(batchKey, List.of("t1"), 201);
        recall(batchKey, "u", "提前召回", "CK-R", 409);
