        String changed = objectMapper.writeValueAsString(new CreateCmd("CK-1", batchKey + "-X",
                "p", "n-changed", Instant.parse("2026-03-01T00:00:00Z"), List.of("t1")));
        mockMvc.perform(post("/api/batches")
